		expression = Call(G("sqlglot.optimizer.qualify.qualify"), Call(G("sqlglot.parse_one"), "SELECT * FROM t UNPIVOT(revenue FOR month IN (jan, feb)) AS u", Kw("dialect", "tsql")), Kw("schema", schema), Kw("dialect", "tsql"))
