func test_tsql_TestTSQL_test_datepart(self *Case, a Args) Value {
	var datepart_formats, formats, canonical, fmt, select_datepart_formats Value
	_ = []Value{datepart_formats, formats, canonical, fmt, select_datepart_formats}
	self.Do(1889, func() {
		datepart_formats = NewTuple(NewTuple(NewTuple("QUARTER", "qq", "q"), "QUARTER"), NewTuple(NewTuple("YEAR", "yy", "yyyy"), "YEAR"), NewTuple(NewTuple("HOUR", "hh"), "HOUR"), NewTuple(NewTuple("MINUTE", "mi", "n"), "MINUTE"), NewTuple(NewTuple("SECOND", "ss", "s"), "SECOND"), NewTuple(NewTuple("MILLISECOND", "ms"), "MILLISECOND"), NewTuple(NewTuple("MICROSECOND", "mcs"), "MICROSECOND"), NewTuple(NewTuple("NANOSECOND", "ns"), "NANOSECOND"), NewTuple(NewTuple("WEEKDAY", "dw"), "WEEKDAY"), NewTuple(NewTuple("TZOFFSET", "tz"), "TZOFFSET"), NewTuple(NewTuple("MONTH", "mm", "m"), "MONTH"), NewTuple(NewTuple("DAYOFYEAR", "dy", "y"), "DAYOFYEAR"), NewTuple(NewTuple("DAY", "dd", "d"), "DAY"))
	})
	for _, item_ := range Iter(datepart_formats) {
		Unpack(item_, &formats, &canonical)
		for _, item_ := range Iter(formats) {
			fmt = item_
			self.SubTest(func() {
				self.Do(1908, func() {
					self.ValidateIdentity(F("DATEPART(", FV{V: fmt}, ", x)"), F("DATEPART(", FV{V: canonical}, ", x)"))
				})
			}, F("Testing DATEPART where part is: ", FV{V: fmt}))
		}
	}
	self.Do(1913, func() {
		select_datepart_formats = NewTuple(NewTuple(NewTuple("WEEK", "WW", "WK"), "WEEK"), NewTuple(NewTuple("ISOWK", "ISOWW", "ISO_WEEK"), "ISO_WEEK"))
	})
	for _, item_ := range Iter(select_datepart_formats) {
		Unpack(item_, &formats, &canonical)
		for _, item_ := range Iter(formats) {
			fmt = item_
			self.SubTest(func() {
				self.Do(1921, func() {
					self.ValidateIdentity(F("SELECT DATEPART(", FV{V: fmt}, ", '2024-11-21')"), F("SELECT DATEPART(", FV{V: canonical}, ", '2024-11-21')"))
				})
			}, F("Testing DATEPART where part is: ", FV{V: fmt}))
		}
	}
	self.L(1926).ValidateAll("SELECT DATEPART(month,'1970-01-01')", Kw("write", NewDict("spark", "SELECT EXTRACT(month FROM '1970-01-01')", "tsql", "SELECT DATEPART(month, '1970-01-01')")))
	self.L(1933).ValidateAll("SELECT DATEPART(YEAR, CAST('2017-01-01' AS DATE))", Kw("read", NewDict("postgres", "SELECT DATE_PART('YEAR', '2017-01-01'::DATE)")), Kw("write", NewDict("postgres", "SELECT EXTRACT(YEAR FROM CAST('2017-01-01' AS DATE))", "spark", "SELECT EXTRACT(YEAR FROM CAST('2017-01-01' AS DATE))", "tsql", "SELECT DATEPART(YEAR, CAST('2017-01-01' AS DATE))")))
	self.L(1944).ValidateAll("SELECT DATEPART(MONTH, CAST('2017-03-01' AS DATE))", Kw("read", NewDict("postgres", "SELECT DATE_PART('month', '2017-03-01'::DATE)")), Kw("write", NewDict("postgres", "SELECT EXTRACT(MONTH FROM CAST('2017-03-01' AS DATE))", "spark", "SELECT EXTRACT(MONTH FROM CAST('2017-03-01' AS DATE))", "tsql", "SELECT DATEPART(MONTH, CAST('2017-03-01' AS DATE))")))
	self.L(1955).ValidateAll("SELECT DATEPART(DAY, CAST('2017-01-02' AS DATE))", Kw("read", NewDict("postgres", "SELECT DATE_PART('day', '2017-01-02'::DATE)")), Kw("write", NewDict("postgres", "SELECT EXTRACT(DAY FROM CAST('2017-01-02' AS DATE))", "spark", "SELECT EXTRACT(DAY FROM CAST('2017-01-02' AS DATE))", "tsql", "SELECT DATEPART(DAY, CAST('2017-01-02' AS DATE))")))
	self.L(1966).ValidateIdentity(`SELECT DATEPART("dd", x)`, "SELECT DATEPART(DAY, x)")
	return nil
}

