func test_tsql_TestTSQL_test_bare_table_hints(self *Case, a Args) Value {
	var table, alias, expected, expression, hint, sql Value
	_ = []Value{table, alias, expected, expression, hint, sql}
	for _, item_ := range Iter(NewTuple("t", "dbo.t", "[dbo].[t]", "[count]", "[left]", "[cast]", "#t", "[#t]", "##t", "[##t]")) {
		table = item_
		for _, item_ := range Iter(NewTuple("", " AS s", " s")) {
			alias = item_
			self.SubTest(func() {
				self.Do(2607, func() {
					expected = F("SELECT * FROM ", FV{V: table}, FV{V: IfV(alias, func() Value { return " AS s" }, func() Value { return "" })}, " WITH (NOLOCK)")
				})
				self.Do(2608, func() {
					expression = self.ValidateIdentity(F("SELECT * FROM ", FV{V: table}, FV{V: alias}, " (NOLOCK)"), expected)
				})
				self.Do(2611, func() { self.AssertEqual(expression, Call(G("sqlglot.parse_one"), expected, Kw("read", "tsql"))) })
				if Truth(alias) {
					self.Do(2613, func() {
						expression = self.ValidateIdentity(F("SELECT * FROM ", FV{V: table}, " (NOLOCK)", FV{V: alias}), expected)
					})
					self.Do(2616, func() { self.AssertEqual(expression, Call(G("sqlglot.parse_one"), expected, Kw("read", "tsql"))) })
				}
			}, Kw("table", table), Kw("alias", alias))
		}
	}
	for _, item_ := range Iter(NewTuple(" AS s", " s")) {
		alias = item_
		self.SubTest(func() {
			self.Do(2620, func() { expected = "SELECT * FROM server.db.dbo.t AS s WITH (NOLOCK)" })
			self.Do(2621, func() {
				expression = self.ValidateIdentity(F("SELECT * FROM server.db.dbo.t", FV{V: alias}, " (NOLOCK)"), expected)
			})
			self.Do(2624, func() { self.AssertEqual(expression, Call(G("sqlglot.parse_one"), expected, Kw("read", "tsql"))) })
		}, Kw("alias", alias))
	}
	for _, item_ := range Iter(NewTuple("NOLOCK", "READUNCOMMITTED", "UPDLOCK", "REPEATABLEREAD", "SERIALIZABLE", "READCOMMITTED", "TABLOCK", "TABLOCKX", "PAGLOCK", "ROWLOCK", "NOWAIT", "READPAST", "XLOCK", "SNAPSHOT", "NOEXPAND")) {
		hint = item_
		self.SubTest(func() {
			self.Do(2644, func() {
				self.ValidateIdentity(F("SELECT * FROM dbo.t (", FV{V: M(hint, "lower")}, ")"), F("SELECT * FROM dbo.t WITH (", FV{V: M(hint, "lower")}, ")"))
			})
		}, Kw("hint", hint))
	}
	self.L(2649).ValidateIdentity("UPDATE dbo.t (ROWLOCK) SET x = 1", "UPDATE dbo.t WITH (ROWLOCK) SET x = 1")
	self.L(2652).ValidateIdentity("DELETE FROM dbo.t (ROWLOCK)", "DELETE FROM dbo.t WITH (ROWLOCK)")
	self.L(2653).ValidateIdentity("SELECT * FROM dbo.t (NOLOCK) JOIN dbo.u AS u (ROWLOCK) ON t.id = u.id", "SELECT * FROM dbo.t WITH (NOLOCK) JOIN dbo.u AS u WITH (ROWLOCK) ON t.id = u.id")
	self.L(2657).ValidateIdentity("SELECT * FROM dbo.t (NOLOCK) AS s JOIN dbo.u AS u ON s.id = u.id", "SELECT * FROM dbo.t AS s WITH (NOLOCK) JOIN dbo.u AS u ON s.id = u.id")
	self.L(2661).ValidateIdentity("SELECT * FROM dbo.t AS s /* alias */ (NOLOCK /* hint */)", "SELECT * FROM dbo.t AS s /* alias */ WITH (NOLOCK /* hint */)")
	self.L(2665).ValidateIdentity("INSERT INTO dbo.t (nolock) SELECT 1")
	self.L(2666).ValidateIdentity("UPDATE s SET x = 1 FROM dbo.t AS s (ROWLOCK) JOIN dbo.u AS u ON s.id = u.id", "UPDATE s SET x = 1 FROM dbo.t AS s WITH (ROWLOCK) JOIN dbo.u AS u ON s.id = u.id")
	self.L(2670).ValidateIdentity("SELECT * FROM dbo.t AS s (NOLOCK) PIVOT(SUM(x) FOR id IN ([1])) AS p", "SELECT * FROM dbo.t AS s WITH (NOLOCK) PIVOT(SUM(x) FOR id IN ([1])) AS p")
	self.L(2674).ValidateAll("SELECT * FROM dbo.t (NOLOCK)", Kw("write", NewDict("tsql", "SELECT * FROM dbo.t WITH (NOLOCK)", "spark", "SELECT * FROM dbo.t")))
	for _, item_ := range Iter(NewTuple("SELECT s.nolock FROM (SELECT 1 AS x) AS s(nolock)", "SELECT s.nolock FROM (VALUES (1)) AS s(nolock)", "SELECT s.nolock.query('.') FROM dbo.t CROSS APPLY t.doc.nodes('/root') AS s(nolock)", "SELECT * FROM dbo.FN(1)", "SELECT * FROM dbo.FN(1) AS s", "SELECT * FROM dbo.FN('NOLOCK')", "SELECT * FROM dbo.FN(@NOLOCK)", "SELECT * FROM dbo.src CROSS APPLY dbo.fn(NOLOCK)", "SELECT * FROM dbo.src CROSS APPLY dbo.fn(x)", "SELECT * FROM dbo.src CROSS APPLY dbo.fn([NOLOCK])", "SELECT * FROM dbo.src CROSS APPLY dbo.fn(NOLOCK, 1)")) {
		sql = item_
		self.SubTest(func() {
			self.Do(2696, func() { expression = self.ValidateIdentity(sql) })
			self.Do(2697, func() { M(self, "assertIsNone", M(expression, "find", A(G("sqlglot.exp"), "WithTableHint"))) })
		}, Kw("sql", sql))
	}
	return nil
}

